"""Weighted interval selection with a cooldown (calendar_windows).

The operation selects a set of half-open windows that are mutually compatible
under ``end + cooldown <= start`` and maximises total value.  Ties are broken
by choosing the lexicographically smallest *sorted* list of normalised ids
(shorter equal-prefix lists are smaller).
"""

from bisect import bisect_right


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _require_int(value, label):
    if not _is_int(value):
        raise ValueError("%s must be an integer, got %s" % (label, type(value).__name__))
    return value


def transform(payloads, contract):
    """Run the ``weighted_intervals`` operation over ``payloads``.

    ``payloads`` strictly follows ``contract["inputs"]``; only the first
    payload is consumed by this operation.
    """
    if contract.get("operation") != "weighted_intervals":
        raise ValueError("unexpected operation: %r" % (contract.get("operation"),))
    name = contract["name"]

    cooldown = _require_int(contract.get("cooldown"), "cooldown")
    if cooldown < 0:
        raise ValueError("cooldown must be >= 0")

    if not payloads:
        raise ValueError("missing input payload")
    first = payloads[0]
    if not isinstance(first, dict):
        raise ValueError("first input must be an object with a 'windows' list")

    raw_windows = first.get("windows")
    if not isinstance(raw_windows, list):
        raise ValueError("'windows' must be a list")

    windows = []
    seen = set()
    for idx, win in enumerate(raw_windows):
        if not isinstance(win, dict):
            raise ValueError("windows[%d] must be an object" % idx)
        wid = win.get("id")
        if not isinstance(wid, str):
            raise ValueError("windows[%d].id must be a string" % idx)
        norm = wid.strip()
        if not norm:
            raise ValueError("windows[%d].id must be non-empty" % idx)
        if norm in seen:
            raise ValueError("duplicate window id: %r" % norm)
        seen.add(norm)

        start = _require_int(win.get("start"), "windows[%d].start" % idx)
        end = _require_int(win.get("end"), "windows[%d].end" % idx)
        value = _require_int(win.get("value"), "windows[%d].value" % idx)
        if start < 0:
            raise ValueError("windows[%d].start must be >= 0" % idx)
        if end <= start:
            raise ValueError("windows[%d].end must be > start" % idx)

        windows.append({"id": norm, "start": start, "end": end, "value": value})

    result = _weighted_intervals(windows, cooldown)
    return {"name": name, "result": result}


def _weighted_intervals(windows, cooldown):
    n = len(windows)
    if n == 0:
        return {"selected": [], "value": 0}

    # Deterministic processing order: increasing end, then start, then id.
    order = sorted(
        range(n),
        key=lambda i: (windows[i]["end"], windows[i]["start"], windows[i]["id"]),
    )
    ends = [windows[i]["end"] for i in order]
    starts = [windows[i]["start"] for i in order]
    vals = [windows[i]["value"] for i in order]
    ids = [windows[i]["id"] for i in order]

    def compatible(a, b):
        return ends[a] + cooldown <= starts[b] or ends[b] + cooldown <= starts[a]

    # Maximum total value (standard weighted interval scheduling DP).
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        p = bisect_right(ends, starts[i - 1] - cooldown, 0, i - 1)
        dp[i] = max(dp[i - 1], vals[i - 1] + dp[p])
    best_value = dp[n]

    # An optimal value of 0 means the empty selection wins outright.
    if best_value == 0:
        return {"selected": [], "value": 0}

    def max_independent(idx_list):
        """Max value over an independent subset of ``idx_list`` (end order)."""
        if not idx_list:
            return 0
        es = [ends[i] for i in idx_list]
        ss = [starts[i] for i in idx_list]
        vs = [vals[i] for i in idx_list]
        m = len(idx_list)
        d = [0] * (m + 1)
        for k in range(1, m + 1):
            p = bisect_right(es, ss[k - 1] - cooldown, 0, k - 1)
            d[k] = max(d[k - 1], vs[k - 1] + d[p])
        return d[m]

    NEG = float("-inf")

    def constrained_max(inc, exc):
        """Max value of an independent set containing ``inc``, avoiding ``exc``."""
        inc = set(inc)
        exc = set(exc)
        if inc & exc:
            return NEG
        inc_sorted = sorted(inc)
        for a_idx in range(len(inc_sorted)):
            for b_idx in range(a_idx + 1, len(inc_sorted)):
                if not compatible(inc_sorted[a_idx], inc_sorted[b_idx]):
                    return NEG
        base = sum(vals[i] for i in inc)
        available = [
            i
            for i in range(n)
            if i not in inc and i not in exc and all(compatible(i, c) for c in inc)
        ]
        return base + max_independent(available)

    def feasible(inc, exc):
        return constrained_max(inc, exc) == best_value

    # Greedy construction of the lexicographically smallest sorted id list among
    # maximum-value selections.  Process ids in ascending string order; an id is
    # taken as the next element of the sorted list exactly when it is the first
    # (smallest) id that can still extend the current prefix to a max-value set.
    by_id = sorted(range(n), key=lambda i: ids[i])
    selected = set()
    excluded = set()

    def selected_value():
        return sum(vals[i] for i in selected)

    pos = 0
    while selected_value() != best_value:
        found = False
        while pos < n:
            x = by_id[pos]
            pos += 1
            if x in selected or x in excluded:
                continue
            if feasible(selected | {x}, excluded):
                selected.add(x)
                found = True
                break
            excluded.add(x)
        if not found:
            raise ValueError("internal error: no feasible extension found")

    return {
        "selected": sorted(ids[i] for i in selected),
        "value": best_value,
    }

