"""Skill- and capacity-constrained job assignment (worker_assignment).

Each job is assigned to exactly one worker that has the matching skill, such
that the sum of durations assigned to a worker does not exceed its capacity.
The objective is hierarchical: maximise total affinity, then minimise total
``cost * duration``, then minimise the lexicographic order of the
``(job, worker)`` tuples listed in ascending job-id order.
"""


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _require_int(value, label):
    if not _is_int(value):
        raise ValueError("%s must be an integer, got %s" % (label, type(value).__name__))
    return value


def _nonempty_str(value, label):
    if not isinstance(value, str):
        raise ValueError("%s must be a string, got %s" % (label, type(value).__name__))
    if not value.strip():
        raise ValueError("%s must be non-empty" % label)
    return value


def transform(payloads, contract):
    """Run the ``capacity_assignment`` operation over ``payloads``."""
    if contract.get("operation") != "capacity_assignment":
        raise ValueError("unexpected operation: %r" % (contract.get("operation"),))
    name = contract["name"]

    if not payloads:
        raise ValueError("missing input payload")
    first = payloads[0]
    if not isinstance(first, dict):
        raise ValueError("first input must be an object with 'jobs' and 'workers'")

    raw_jobs = first.get("jobs")
    raw_workers = first.get("workers")
    if not isinstance(raw_jobs, list):
        raise ValueError("'jobs' must be a list")
    if not isinstance(raw_workers, list):
        raise ValueError("'workers' must be a list")

    # --- parse jobs ---------------------------------------------------------
    jobs = []
    seen_job_ids = set()
    for idx, job in enumerate(raw_jobs):
        if not isinstance(job, dict):
            raise ValueError("jobs[%d] must be an object" % idx)
        jid = _nonempty_str(job.get("id"), "jobs[%d].id" % idx)
        if jid.strip() in seen_job_ids:
            raise ValueError("duplicate job id: %r" % jid)
        seen_job_ids.add(jid.strip())
        skill = _nonempty_str(job.get("skill"), "jobs[%d].skill" % idx)
        duration = _require_int(job.get("duration"), "jobs[%d].duration" % idx)
        if duration < 1:
            raise ValueError("jobs[%d].duration must be >= 1" % idx)
        jobs.append({"id": jid, "skill": skill, "duration": duration})

    # --- parse workers ------------------------------------------------------
    workers = []
    seen_worker_ids = set()
    for idx, worker in enumerate(raw_workers):
        if not isinstance(worker, dict):
            raise ValueError("workers[%d] must be an object" % idx)
        wid = _nonempty_str(worker.get("id"), "workers[%d].id" % idx)
        if wid.strip() in seen_worker_ids:
            raise ValueError("duplicate worker id: %r" % wid)
        seen_worker_ids.add(wid.strip())

        skills = worker.get("skills")
        if not isinstance(skills, list):
            raise ValueError("workers[%d].skills must be a list" % idx)
        for s_idx, s in enumerate(skills):
            _nonempty_str(s, "workers[%d].skills[%d]" % (idx, s_idx))

        capacity = _require_int(worker.get("capacity"), "workers[%d].capacity" % idx)
        if capacity < 0:
            raise ValueError("workers[%d].capacity must be >= 0" % idx)
        cost = _require_int(worker.get("cost"), "workers[%d].cost" % idx)
        if cost < 0:
            raise ValueError("workers[%d].cost must be >= 0" % idx)

        affinity = worker.get("affinity")
        if not isinstance(affinity, dict):
            raise ValueError("workers[%d].affinity must be an object" % idx)
        clean_affinity = {}
        for key, val in affinity.items():
            if not isinstance(key, str):
                raise ValueError("workers[%d].affinity keys must be strings" % idx)
            clean_affinity[key] = _require_int(
                val, "workers[%d].affinity[%r]" % (idx, key)
            )

        workers.append(
            {
                "id": wid,
                "skills": list(skills),
                "capacity": capacity,
                "cost": cost,
                "affinity": clean_affinity,
            }
        )

    # --- consume subsequent component results --------------------------------
    selected_set = None
    makespan = None
    for payload in payloads[1:]:
        if not isinstance(payload, dict) or set(payload.keys()) != {"name", "result"}:
            raise ValueError("subsequent input must be a component envelope")
        result = payload["result"]
        if not isinstance(result, dict):
            raise ValueError("component result must be an object")

        if "selected" in result:
            sel = result["selected"]
            if not isinstance(sel, list):
                raise ValueError("'selected' must be a list")
            selected_set = set(sel)
        if "makespan" in result:
            msp = _require_int(result["makespan"], "makespan")
            if msp < 0:
                raise ValueError("makespan must be >= 0")
            makespan = msp

    # Apply filters in the documented order: selected first, then makespan.
    active_workers = []
    for worker in workers:
        if selected_set is not None and worker["id"] not in selected_set:
            continue
        cap = worker["capacity"]
        if makespan is not None:
            cap = min(cap, makespan)
        active_workers.append(dict(worker, capacity=cap))

    result = _solve(jobs, active_workers)
    return {"name": name, "result": result}


def _solve(jobs, workers):
    if not jobs:
        return {"feasible": True, "score": 0, "cost": 0, "assignments": []}

    # Deterministic job order (ascending id); also the order of assignments.
    job_list = sorted(jobs, key=lambda j: j["id"])
    worker_by_id = {w["id"]: w for w in workers}

    # Candidate workers per job (skill match only; capacity checked during search).
    candidates = {}
    for job in job_list:
        cands = [
            w for w in workers if job["skill"] in w["skills"]
        ]
        candidates[job["id"]] = cands

    # Upper bound on remaining affinity for score pruning.
    max_affinity = {}
    for job in job_list:
        cands = candidates[job["id"]]
        max_affinity[job["id"]] = max(
            (w["affinity"].get(job["id"], 0) for w in cands), default=0
        )
    suffix_ub = [0] * (len(job_list) + 1)
    for i in range(len(job_list) - 1, -1, -1):
        suffix_ub[i] = suffix_ub[i + 1] + max_affinity[job_list[i]["id"]]

    n = len(job_list)
    remaining_cap = {w["id"]: w["capacity"] for w in workers}
    assign = []

    best = None  # (score, cost, worker_sequence)

    def better(a, b):
        if a[0] != b[0]:
            return a[0] > b[0]
        if a[1] != b[1]:
            return a[1] < b[1]
        return a[2] < b[2]

    def dfs(i, score, cost):
        nonlocal best
        if i == n:
            candidate = (score, cost, tuple(assign))
            if best is None or better(candidate, best):
                best = candidate
            return

        job = job_list[i]
        cands = candidates[job["id"]]
        for w in cands:
            if remaining_cap[w["id"]] < job["duration"]:
                continue
            new_score = score + w["affinity"].get(job["id"], 0)
            new_cost = cost + w["cost"] * job["duration"]

            # Prune branches that cannot beat the current best solution.
            if best is not None:
                if new_score + suffix_ub[i + 1] < best[0]:
                    continue
                if new_score == best[0] and new_cost > best[1]:
                    continue
                if new_score < best[0] and new_score + suffix_ub[i + 1] <= best[0]:
                    continue

            remaining_cap[w["id"]] -= job["duration"]
            assign.append(w["id"])
            dfs(i + 1, new_score, new_cost)
            assign.pop()
            remaining_cap[w["id"]] += job["duration"]

    dfs(0, 0, 0)

    if best is None:
        return {"feasible": False, "score": 0, "cost": 0, "assignments": []}

    score, cost, seq = best
    assignments = [
        {"job": job_list[i]["id"], "worker": seq[i]} for i in range(n)
    ]
    return {
        "feasible": True,
        "score": score,
        "cost": cost,
        "assignments": assignments,
    }

