"""Dependency-graph critical path analysis (job_order).

Computes topological waves, earliest finish times, makespan and a deterministically
tie-broken critical path.  Optional subsequent assignment results (carrying a
``feasible`` field) add per-worker ordering edges between consecutively ordered
jobs.
"""


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def _require_int(value, label):
    if not _is_int(value):
        raise ValueError("%s must be an integer, got %s" % (label, type(value).__name__))
    return value


def transform(payloads, contract):
    """Run the ``critical_path`` operation over ``payloads``."""
    if contract.get("operation") != "critical_path":
        raise ValueError("unexpected operation: %r" % (contract.get("operation"),))
    name = contract["name"]

    if not payloads:
        raise ValueError("missing input payload")
    first = payloads[0]
    if not isinstance(first, dict):
        raise ValueError("first input must be an object with a 'nodes' list")

    raw_nodes = first.get("nodes")
    if not isinstance(raw_nodes, list):
        raise ValueError("'nodes' must be a list")

    # --- parse nodes --------------------------------------------------------
    nodes = {}
    for idx, node in enumerate(raw_nodes):
        if not isinstance(node, dict):
            raise ValueError("nodes[%d] must be an object" % idx)
        nid = node.get("id")
        if not isinstance(nid, str):
            raise ValueError("nodes[%d].id must be a string" % idx)
        norm = nid.strip()
        if not norm:
            raise ValueError("nodes[%d].id must be non-empty" % idx)
        if norm in nodes:
            raise ValueError("duplicate node id: %r" % norm)

        duration = _require_int(node.get("duration"), "nodes[%d].duration" % idx)
        if duration < 0:
            raise ValueError("nodes[%d].duration must be >= 0" % idx)

        deps = node.get("deps")
        if not isinstance(deps, list):
            raise ValueError("nodes[%d].deps must be a list" % idx)
        clean_deps = []
        for d in deps:
            if not isinstance(d, str):
                raise ValueError("nodes[%d].deps entries must be strings" % idx)
            clean_deps.append(d.strip())

        nodes[norm] = {
            "id": norm,
            "duration": duration,
            "deps": clean_deps,
        }

    # --- validate the base dependency graph --------------------------------
    for nid, node in nodes.items():
        if len(set(node["deps"])) != len(node["deps"]):
            raise ValueError("duplicate dependency in node %r" % nid)
        for dep in node["deps"]:
            if dep not in nodes:
                raise ValueError("unknown dependency %r in node %r" % (dep, nid))
            if dep == nid:
                raise ValueError("self dependency in node %r" % nid)

    # Edges are stored as predecessor sets keyed by successor.
    preds = {nid: set() for nid in nodes}
    for nid, node in nodes.items():
        for dep in node["deps"]:
            preds[nid].add(dep)

    # --- consume subsequent assignment results -------------------------------
    for payload in payloads[1:]:
        if not isinstance(payload, dict) or set(payload.keys()) != {"name", "result"}:
            raise ValueError("subsequent input must be a component envelope")
        result = payload["result"]
        if not isinstance(result, dict):
            raise ValueError("component result must be an object")

        if "feasible" not in result:
            continue

        feasible = result["feasible"]
        if not isinstance(feasible, bool):
            raise ValueError("'feasible' must be a boolean")
        if feasible is False:
            return {
                "name": name,
                "result": {
                    "blocked": True,
                    "waves": [],
                    "critical_path": [],
                    "makespan": 0,
                    "earliest_finish": {},
                },
            }

        # feasible == True: add per-worker ordering edges from assignments.
        assignments = result.get("assignments")
        if not isinstance(assignments, list):
            raise ValueError("'assignments' must be a list")

        by_worker = {}
        for a_idx, a in enumerate(assignments):
            if not isinstance(a, dict):
                raise ValueError("assignments[%d] must be an object" % a_idx)
            job = a.get("job")
            worker = a.get("worker")
            if not isinstance(job, str):
                raise ValueError("assignments[%d].job must be a string" % a_idx)
            if not isinstance(worker, str):
                raise ValueError("assignments[%d].worker must be a string" % a_idx)
            job = job.strip()
            if job not in nodes:
                raise ValueError("unknown assigned job: %r" % job)
            by_worker.setdefault(worker, []).append(job)

        for worker, job_ids in by_worker.items():
            job_ids = sorted(job_ids)
            for a, b in zip(job_ids, job_ids[1:]):
                preds[b].add(a)

    # --- compute waves, finishes and critical path ---------------------------
    result = _analyse(nodes, preds)
    return {"name": name, "result": result}


def _analyse(nodes, preds):
    all_ids = list(nodes.keys())
    if not all_ids:
        return {
            "blocked": False,
            "waves": [],
            "critical_path": [],
            "makespan": 0,
            "earliest_finish": {},
        }

    # Kahn-style layering; a stuck pass indicates a cycle.
    remaining = set(all_ids)
    waves = []
    while remaining:
        ready = [nid for nid in remaining if not (preds[nid] & remaining)]
        if not ready:
            raise ValueError("cycle detected in dependency graph")
        ready.sort()
        waves.append(ready)
        remaining -= set(ready)

    topo = [nid for wave in waves for nid in wave]

    finish = {}
    path = {}  # lexicographically smallest longest path ending at each node
    for nid in topo:
        if preds[nid]:
            max_fin = max(finish[p] for p in preds[nid])
            candidates = [p for p in preds[nid] if finish[p] == max_fin]
            best_pred = min(candidates, key=lambda p: path[p])
            finish[nid] = nodes[nid]["duration"] + max_fin
            path[nid] = path[best_pred] + [nid]
        else:
            finish[nid] = nodes[nid]["duration"]
            path[nid] = [nid]

    makespan = max(finish.values())
    terminals = [nid for nid in all_ids if finish[nid] == makespan]
    critical_path = path[min(terminals, key=lambda nid: path[nid])]

    earliest_finish = {nid: finish[nid] for nid in all_ids}

    return {
        "blocked": False,
        "waves": waves,
        "critical_path": critical_path,
        "makespan": makespan,
        "earliest_finish": earliest_finish,
    }

