"""Recompute every component, then integrate and build the final report.

Execution order is derived from the actual input/output dependencies recorded in
each ``contract.json`` (not from file-name sorting), so a component only runs
once all of its upstream component outputs already exist.
"""

import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def contracts():
    return sorted(
        p for p in ROOT.rglob("contract.json") if "outputs" not in p.relative_to(ROOT).parts
    )


def main():
    cpaths = contracts()
    if not cpaths:
        raise ValueError("no component contracts found")

    info = {}
    for cpath in cpaths:
        info[cpath] = json.loads(cpath.read_text(encoding="utf-8"))

    # Which component produces each output path.
    output_owner = {}
    for cpath, c in info.items():
        if c["output"] in output_owner:
            raise ValueError("duplicate output path: %s" % c["output"])
        output_owner[c["output"]] = cpath

    done = set()
    remaining = set(info.keys())

    while remaining:
        progressed = False
        for cpath in sorted(remaining, key=lambda p: info[p]["name"]):
            c = info[cpath]
            ready = True
            for inp in c["inputs"]:
                if inp in output_owner and output_owner[inp] not in done:
                    ready = False
                    break
            if ready:
                render = cpath.with_name("render.py")
                if not render.is_file():
                    raise ValueError("missing render implementation: %s" % render)
                subprocess.run([sys.executable, str(render)], cwd=ROOT, check=True)
