        if not progressed:
            raise ValueError("cycle or missing dependency among components")

    subprocess.run([sys.executable, str(ROOT / "integrate.py")], cwd=ROOT, check=True)
    subprocess.run(
        [sys.executable, str(ROOT / "final_report.py")], cwd=ROOT, check=True
    )


if __name__ == "__main__":
    main()

